import{_ as t,o,c as i,a7 as r}from"./chunks/framework.xMNG87v2.js";const u=JSON.parse('{"title":"API versioning","description":"Versioning policy of Axolotl-PM.","frontmatter":{"title":"API versioning","outline":"deep","description":"Versioning policy of Axolotl-PM.","head":[["link",{"rel":"canonical","href":"https://axolotl-pm.org/docs/developers/plugin-docs/api-version-spec"}]]},"headers":[],"relativePath":"docs/developers/plugin-docs/api-version-spec.md","filePath":"docs/developers/plugin-docs/api-version-spec.md","lastUpdated":1790689997000}'),n={name:"docs/developers/plugin-docs/api-version-spec.md"};function s(a,e,d,l,h,c){return o(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="api-versioning" tabindex="-1">API versioning <a class="header-anchor" href="#api-versioning" aria-label="Permalink to &quot;API versioning&quot;">​</a></h1><p>Axolotl-PM plugins are required to declare which API versions they are compatible with. This is used to decide whether or not to load a plugin, and to gracefully degrade when the plugin is not compatible with the given server version.</p><p>As of Axolotl-PM 3.0.0, the API version is the same as the server version. This version is a semantic <code>major.minor.patch</code> version number. Read more about <a href="https://semver.org/" target="_blank" rel="noreferrer">semantic versioning</a>.</p><h2 id="how-the-api-version-is-changed" tabindex="-1">How the API version is changed <a class="header-anchor" href="#how-the-api-version-is-changed" aria-label="Permalink to &quot;How the API version is changed&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Type</th><th>Example</th><th>Description</th></tr></thead><tbody><tr><td>Major</td><td>5.33.0 -&gt; 6.0.0</td><td>Changing or deleting features</td></tr><tr><td>Minor</td><td>5.33.0 -&gt; 5.34.0</td><td>New features were added, existing ones were deprecated, or the supported Minecraft version was changed</td></tr><tr><td>Patch</td><td>5.33.0 -&gt; 5.33.1</td><td>Bugs were fixed</td></tr></tbody></table><h2 id="compatibility-checking-examples" tabindex="-1">Compatibility checking examples <a class="header-anchor" href="#compatibility-checking-examples" aria-label="Permalink to &quot;Compatibility checking examples&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Server version</th><th>Plugin version</th><th>Compatible</th><th>Reason</th></tr></thead><tbody><tr><td>4.0.0</td><td>3.0.0</td><td>NO</td><td>Major versions are different.</td></tr><tr><td>3.1.0</td><td>3.0.0</td><td>YES</td><td>Server has a greater minor version than the plugin, guaranteeing compatibility.</td></tr><tr><td>3.0.0</td><td>3.1.0</td><td>NO</td><td>Plugin requires new features not found in the given server version</td></tr><tr><td>3.0.1</td><td>3.0.0</td><td>YES</td><td>Server has a greater patch version than the plugin, guaranteeing compatibility.</td></tr><tr><td>3.0.0</td><td>3.0.1</td><td>NO</td><td>Plugin requires newer bug fixes not found in the given server version</td></tr></tbody></table><h2 id="how-to-choose-your-supported-api-version" tabindex="-1">How to choose your supported API version <a class="header-anchor" href="#how-to-choose-your-supported-api-version" aria-label="Permalink to &quot;How to choose your supported API version&quot;">​</a></h2><p>You should choose the <strong>minimum version that supports the things that you need</strong>.</p><p>For example, if the feature you want was first added in <code>3.1.0</code>, you can require <code>3.1.0</code> as a minimum even if the currently supported version is <code>3.2.0</code>. This is to ensure that users get a smoother experience no matter what version of Axolotl-PM they are using.</p><p>Of course, you should test your plugin on your minimum version to make sure that everything works correctly. However, it may of course not make sense to require a lower version if the earlier versions are end-of-life.</p><h2 id="common-pitfalls-and-misconceptions" tabindex="-1">Common pitfalls and misconceptions <a class="header-anchor" href="#common-pitfalls-and-misconceptions" aria-label="Permalink to &quot;Common pitfalls and misconceptions&quot;">​</a></h2><ul><li>The API version <strong>is not a magic number</strong>. Changing it blindly <strong>will not make a plugin magically work</strong> on a version it wasn’t designed for.</li><li>It is <strong>not required to write out every single compatible version</strong> in your plugin’s manifest. Only the <strong>minimum required version of each major version</strong> is required. <ul><li>Good: <code>[3.1.0]</code> (single minimum version), <code>[3.2.0, 4.0.0]</code> (minimum version from two different major branches)</li><li>Bad: <code>[3.1.0, 3.1.1, 3.1.2]</code> - this is <strong>not</strong> desired and the superfluous versions will be ignored.</li></ul></li><li>Ensure that your plugin <strong>actually runs on the versions you specified</strong>. Versions which it a) crashes on, or b) doesn’t work as expected, should be removed from your versions list.</li></ul>',13)])])}const m=t(n,[["render",s]]);export{u as __pageData,m as default};
